parameters.jsCode:
try {
    const text = $('Extract from File').first().json.text;
    const type = $('AI Classifier').first().json.output;
    let data = $('AI Agent').first().json;

    // Tenter de parser la réponse si c'est une string
    if (typeof data === 'string') {
        const match = data.match(/\{[\s\S]*\}/);
        if (match) {
            data = JSON.parse(match[0]);
        } else {
            data = {};
        }
    }

    const isValid = data && Object.keys(data).length > 0;

    return {
        ...data,
        document_type: type,
        processed_at: new Date().toISOString(),
        extraction_success: isValid,
        trigger_create: true,
        trigger_email: true,
    };

} catch (error) {
    return {
        extraction_success: true,
        error: error.message,
        trigger_create: true,
        trigger_email: true,
    };
}
